application.css:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700&display=swap');
:root{--ink:#182522;--muted:#71817b;--cream:#f6f8f5;--card:#fff;--line:#e1e9e4;--green:#1d6252;--mint:#dff1e9;--coral:#e8785e;}
*{box-sizing:border-box}body{margin:0;background:var(--cream);color:var(--ink);font-family:'DM Sans',sans-serif} .app-shell{max-width:1120px;margin:auto;padding:58px 28px 30px}.hero{display:flex;align-items:flex-start;gap:20px;margin-bottom:43px}.brand-mark{width:48px;height:48px;border-radius:15px;background:var(--green);color:#fff;display:grid;place-items:center;font-size:25px;box-shadow:0 8px 18px #1d625233}.eyebrow,.section-label{margin:0 0 9px;color:var(--green);font-size:11px;font-weight:700;letter-spacing:2px}.hero h1{font-family:'Playfair Display',serif;font-size:42px;line-height:1.12;margin:0 0 10px;letter-spacing:-.7px}.subtitle{color:var(--muted);margin:0;font-size:15px}.content-grid{display:grid;grid-template-columns:1fr 1fr;gap:25px;align-items:start}.card{background:var(--card);border:1px solid var(--line);border-radius:20px;padding:30px;box-shadow:0 10px 30px #25382e0a}.card-heading{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:26px}.card h2{font-family:'Playfair Display',serif;font-size:25px;margin:0;letter-spacing:-.3px}.step-badge,.count{display:grid;place-items:center;border-radius:50%;width:34px;height:34px;background:var(--mint);color:var(--green);font-size:12px;font-weight:700}.field-group{margin-bottom:18px}.field-row{display:grid;grid-template-columns:1fr 1fr;gap:14px}.field-group label{display:block;font-size:12px;font-weight:700;margin:0 0 8px;color:#40504a}input,select{width:100%;height:47px;padding:0 13px;border:1px solid var(--line);border-radius:9px;background:#fbfcfb;color:var(--ink);font:inherit;font-size:14px;outline:none;transition:.2s}input:focus,select:focus{border-color:var(--green);box-shadow:0 0 0 3px #dff1e9}input::placeholder{color:#a8b4ae}.primary-button{width:100%;height:50px;border:0;border-radius:9px;background:var(--green);color:#fff;font:600 14px 'DM Sans';cursor:pointer;transition:.2s;margin-top:4px}.primary-button:hover{background:#164d41;transform:translateY(-1px)}.primary-button span{font-size:19px;margin-left:8px}.form-note{font-size:11px;color:#94a19b;text-align:center;margin:15px 0 0}.confirmation{margin-top:18px;padding:12px 14px;border-radius:9px;background:var(--mint);color:var(--green);font-size:13px;font-weight:600}.bookings-heading{margin-bottom:20px}.count{width:30px;height:30px;background:#f1f4f1}.booking-list{min-height:270px}.empty-state{text-align:center;padding:48px 20px;color:var(--muted)}.empty-icon{display:grid;place-items:center;width:52px;height:52px;border-radius:50%;background:#f1f5f1;color:var(--green);font-size:25px;margin:0 auto 15px}.empty-state h3{font-size:15px;margin:0 0 7px;color:var(--ink)}.empty-state p{font-size:12px;margin:0;line-height:1.5}.booking{border:1px solid var(--line);border-radius:12px;padding:17px;margin-bottom:12px;position:relative;border-left:4px solid var(--coral)}.booking-top{display:flex;justify-content:space-between;gap:12px}.booking-name{font-weight:700;font-size:15px;margin:0 0 6px}.booking-type{font-size:11px;color:var(--green);font-weight:700;text-transform:uppercase;letter-spacing:.7px}.booking-details{display:flex;gap:13px;color:var(--muted);font-size:12px;margin-top:13px}.cancel-button{border:0;background:none;color:#b26a5b;font:600 11px 'DM Sans';cursor:pointer;padding:0}.cancel-button:hover{text-decoration:underline}.booking[data-status='cancelled']{border-left-color:#b7c0bb;opacity:.65}.booking[data-status='cancelled'] .booking-name{text-decoration:line-through}.cancelled-label{font-size:11px;color:#84908a;font-weight:700}.bookings-card{min-height:390px}footer{text-align:center;color:#9aa7a0;font-size:11px;margin-top:32px}footer span{padding:0 8px;color:var(--coral)}[hidden]{display:none!important}@media(max-width:760px){.app-shell{padding:35px 17px 25px}.hero h1{font-size:34px}.content-grid{grid-template-columns:1fr}.card{padding:23px}.bookings-card{min-height:0}}

application.javascript:
const form = document.getElementById('booking-form');
const dateInput = document.querySelector('[data-testid="booking-date"]');
const list = document.querySelector('[data-testid="booking-list"]');
const emptyState = document.getElementById('empty-state');
const confirmation = document.querySelector('[data-testid="booking-confirmation"]');
const count = document.getElementById('booking-count');

function todayString() {
  const now = new Date();
  const offset = now.getTimezoneOffset();
  return new Date(now.getTime() - offset * 60000).toISOString().split('T')[0];
}
dateInput.min = todayString();

function formatDate(value) {
  return new Date(value + 'T00:00:00').toLocaleDateString(undefined, {weekday:'short', month:'short', day:'numeric', year:'numeric'});
}
function formatTime(value) {
  return new Date('2000-01-01T' + value).toLocaleTimeString([], {hour:'numeric', minute:'2-digit'});
}
function updateCount() {
  count.textContent = list.querySelectorAll('[data-status="active"]').length;
}
form.addEventListener('submit', function(event) {
  event.preventDefault();
  if (!form.checkValidity()) { form.reportValidity(); return; }
  const data = new FormData(form);
  if (data.get('date') < todayString()) {
    dateInput.setCustomValidity('Please choose today or a future date.');
    dateInput.reportValidity();
    dateInput.setCustomValidity('');
    return;
  }
  emptyState.hidden = true;
  const item = document.createElement('article');
  item.className = 'booking';
  item.dataset.testid = 'booking';
  item.dataset.status = 'active';
  item.innerHTML = '<div class="booking-top"><div><p class="booking-name" data-testid="booking-name-display"></p><span class="booking-type"></span></div><button type="button" class="cancel-button" data-testid="booking-cancel">Cancel</button></div><div class="booking-details"><span class="date-detail"></span><span class="time-detail"></span></div>';
  item.querySelector('[data-testid="booking-name-display"]').textContent = data.get('name');
  item.querySelector('.booking-type').textContent = data.get('type');
  item.querySelector('.date-detail').textContent = formatDate(data.get('date'));
  item.querySelector('.time-detail').textContent = formatTime(data.get('time'));
  item.querySelector('[data-testid="booking-cancel"]').addEventListener('click', function() {
    item.dataset.status = 'cancelled';
    this.remove();
    const label = document.createElement('span');
    label.className = 'cancelled-label';
    label.textContent = 'Cancelled';
    item.querySelector('.booking-top').appendChild(label);
    updateCount();
  });
  list.prepend(item);
  updateCount();
  confirmation.textContent = 'Appointment confirmed for ' + data.get('name') + '!';
  confirmation.hidden = false;
  form.reset();
  dateInput.min = todayString();
});
